/* @autogenerated */
package net.civeira.phylax.features.oauth.tokensecurity.infrastructure.driven;

import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import com.auth0.jwt.JWT;

import net.civeira.phylax.common.infrastructure.CurrentRequest;
import net.civeira.phylax.features.oauth.tokensecurity.domain.KeyInformation;
import net.civeira.phylax.features.oauth.tokensecurity.domain.PublicKeyInformation;
import net.civeira.phylax.features.oauth.tokensecurity.domain.gateway.TokenStoreGateway;

/**
 * Key id that only names the public key (task 0.7) and keys generated outside the requests (task
 * 2.6).
 */
class JoseTokenSignerUnitTest {

  private InMemoryKeys keys;
  private JoseTokenSigner signer;

  @BeforeEach
  void setUp() {
    keys = new InMemoryKeys();
    CurrentRequest current = Mockito.mock(CurrentRequest.class);
    Mockito.when(current.getPublicHost()).thenReturn("https://auth.example.com");
    signer = new JoseTokenSigner(current, Duration.ofDays(1), 1, keys, "", "");
  }

  @Test
  @DisplayName("Signing and the JWKS never generate keys: only the rotation job does")
  void no_key_generation_in_requests() {
    Assertions.assertTrue(signer.keysAsJwks("acme").getKeys().isEmpty());
    Assertions.assertThrows(IllegalStateException.class,
        () -> signer.sign("acme", JWT.create(), Instant.now().plusSeconds(60)));
    Assertions.assertEquals(0, keys.saved.size());

    signer.rotateKeys();

    Assertions.assertFalse(keys.saved.isEmpty());
    int generated = keys.saved.size();
    signer.rotateKeys();
    Assertions.assertEquals(generated, keys.saved.size(), "Enough future keys: nothing to add");
  }

  @Test
  @DisplayName("The kid of a signed token is a public key id of the JWKS, never key material")
  void kid_is_the_public_key_id() {
    signer.rotateKeys();
    String token =
        signer.sign("acme", JWT.create().withIssuer("https://auth.example.com/oauth/openid/acme"),
            Instant.now().plusSeconds(60));

    String kid = JWT.decode(token).getKeyId();
    Assertions.assertTrue(
        signer.keysAsJwks("acme").getKeys().stream().anyMatch(k -> kid.equals(k.getKid())));
    Assertions.assertTrue(keys.saved.stream().noneMatch(k -> k.getPrivateKey().equals(kid)));
    Assertions.assertEquals(kid, signer.verifiedKeypass("acme", token));
    Assertions.assertFalse(signer.verifyTokenPayload("acme", token).isEmpty());
  }

  @Test
  @DisplayName("A token signed before a rotation still verifies afterwards")
  void tokens_survive_rotation() {
    signer.rotateKeys();
    String token =
        signer.sign("acme", JWT.create().withIssuer("https://auth.example.com/oauth/openid/acme"),
            Instant.now().plusSeconds(60));
    keys.shiftCurrent();
    signer.rotateKeys();

    Assertions.assertFalse(signer.verifyTokenPayload("acme", token).isEmpty());
  }

  /**
   * Key ring in memory with the semantics of {@code TokenStoreSqlAdapter}.
   */
  static class InMemoryKeys implements TokenStoreGateway {
    record Stored(KeyInformation key, Instant since, Instant expiration) {
      String getPrivateKey() {
        return key.getPrivateKey();
      }
    }

    final List<Stored> saved = new ArrayList<>();
    private Duration offset = Duration.ZERO;

    void shiftCurrent() {
      offset = offset.plus(Duration.ofDays(1));
    }

    private Instant now() {
      return Instant.now().plus(offset);
    }

    @Override
    public Optional<KeyInformation> currentKey(String tenant) {
      return saved.stream().filter(s -> !s.since().isAfter(now()))
          .max(Comparator.comparing(Stored::expiration)).map(Stored::key);
    }

    @Override
    public Instant nextKeysExpiration(String tenant) {
      return saved.stream().filter(s -> s.since().isAfter(Instant.now())).map(Stored::expiration)
          .max(Comparator.naturalOrder()).orElse(Instant.now());
    }

    @Override
    public List<PublicKeyInformation> listPublicKeys(String tenant) {
      return saved.stream().map(s -> PublicKeyInformation.builder().keyId(s.key().getKeyId())
          .publicKey(s.key().getPublicKey()).build()).toList();
    }

    @Override
    public List<KeyInformation> listKeys(String tenant) {
      return saved.stream().map(Stored::key).toList();
    }

    @Override
    public void saveKey(String tenant, KeyInformation key, Instant since, Duration caducidad) {
      saved.add(new Stored(key, since, since.plus(caducidad)));
    }
  }
}
